      let pct = '';
      if (hasVals && i > 0 && vals[i - 1] > 0) pct = ' <span style="opacity:.85;font-weight:500">(' + Math.round(vals[i] / vals[i - 1] * 100) + '%)</span>';
      const val = hasVals ? '<b style="direction:ltr;unicode-bidi:isolate">' + fmtNum(vals[i]) + '</b> · ' : '';
