    const gap = 12, cw = (W - 12 - gap * (cols - 1)) / cols;
    const bhOf = it => Math.max(54, lines(it.label, cw - 56, 15) * 23 + (it.desc ? lines(it.desc, cw - 56, 13.5) * 21 : 0) + 18);
    const rows = Math.ceil(n / cols); let body = '', y = 6;
