    const R = { foot: (await NX.img(SITE_ROOT + 'assets/monshaat/foot-logo.webp')).data, idea: (await NX.img(SITE_ROOT + 'assets/monshaat/man-idea.webp')).data, think: (await NX.img(SITE_ROOT + 'assets/monshaat/man-think.webp')).data, cover: (await NX.img(SITE_ROOT + 'assets/monshaat/cover.webp', 'jpeg')).data };
